import subprocess, time, sys, os
SESSION = "probe"
COLS = int(os.environ.get("COLS", "100")); ROWS = int(os.environ.get("ROWS", "30"))
def sh(cmd, timeout=20): return subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout).stdout
def send(keys):
    if isinstance(keys,str): keys=[keys]
    args=" ".join(keys); sh(f"tmux send-keys -t {SESSION} {args}")
def restart():
    sh("bash /tmp/lab/mkscratch.sh"); sh("tmux kill-server 2>/dev/null")
    sh(f"tmux new-session -d -s {SESSION} -x {COLS} -y {ROWS} 'bash /tmp/lab/keyprobe.sh'")
    time.sleep(1.3)
    return sh(f"tmux capture-pane -t {SESSION} -p")
def capture():
    return sh(f"tmux capture-pane -t {SESSION} -p")
def difflines(a,b):
    la, lb = a.split("\n"), b.split("\n")
    out=[]
    for i in range(max(len(la),len(lb))):
        x = la[i] if i<len(la) else ""
        y = lb[i] if i<len(lb) else ""
        if x!=y: out.append(f"L{i+1}: {y!r}  (was {x!r})")
    return out
def keyprobe(keys, delay=0.45, esc=True):
    base = restart()
    for k in keys:
        send(k); time.sleep(delay)
        s = capture()
        d = difflines(base, s)
        print(f"--- after {k!r}:")
        for l in d: print("   ", l)
        if not d: print("    (no change)")
        base = s
PYEOF
cd /tmp/lab && python3 -c "
import probe6 as p
p.keyprobe(['S'])
""}

