import subprocess, time, shlex, os
SESSION = "probe"
COLS = int(os.environ.get("COLS", "100")); ROWS = int(os.environ.get("ROWS", "30"))
def sh(cmd, timeout=30):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout).stdout
def send(keys):
    if isinstance(keys,str): keys=[keys]
    sh(f"tmux send-keys -t {SESSION} " + " ".join(keys))
def lit(text):
    sh(f"tmux send-keys -t {SESSION} -l " + shlex.quote(text))
def capture(e=False):
    f = "-e " if e else ""
    return sh(f"tmux capture-pane -t {SESSION} -p {f}")
def kill(): sh("tmux kill-server 2>/dev/null")
def start(startdir="/tmp/scratch", args="", HOME="/tmp/labhome", mk=True, editor=True, rows=None, cols=None):
    global COLS, ROWS
    if rows: ROWS=rows
    if cols: COLS=cols
    if mk: sh("bash /tmp/lab/mkscratch.sh")
    kill()
    pre = []
    pre.append(f"export HOME={HOME}")
    if editor: pre.append("export EDITOR=/tmp/lab/ed.sh; export VISUAL=/tmp/lab/ed.sh")
    pre.append(f"cd {startdir}")
    pre.append(f"/workspace/executable {args} 2>/tmp/lab/err.txt; echo RC=$? > /tmp/lab/rc.txt")
    cmdline = "; ".join(pre) + "; sleep 120"
    sh(f"tmux new-session -d -s {SESSION} -x {COLS} -y {ROWS} {shlex.quote(cmdline)}")
    time.sleep(1.4)
    return capture()
def difflines(a,b):
    la, lb = a.split("\n"), b.split("\n"); out=[]
    for i in range(max(len(la),len(lb))):
        x = la[i] if i<len(la) else ""; y = lb[i] if i<len(lb) else ""
        if x!=y: out.append(f"L{i+1}: {y!r}  (was {x!r})")
    return out
def keytest(keys, startdir="/tmp/scratch", args="", pre=None, delay=0.45, mk=True, show=True, rows=None, cols=None):
    s = start(startdir, args, mk=mk, rows=rows, cols=cols)
    if pre:
        for k in (pre if isinstance(pre,list) else [pre]):
            send(k); time.sleep(delay)
        s = capture()
    for k in keys:
        if isinstance(k,str): k=[k]
        for kk in k: send(kk); time.sleep(delay)
        c = capture()
        d = difflines(s,c)
        print(f"--- after {k!r}:")
        for l in d: print("   ", l[:160])
        if not d: print("    (no change)")
        s = c
def wait(t): time.sleep(t)
PYEOF
cd /tmp/lab && python3 - <<'PYEOF'
import harness as h, time
for start in ['/tmp/scratch','/tmp','/','/etc']:
    s = h.start(start, mk=True)
    h.send(['~']); time.sleep(0.6)
    c=h.capture().split(chr(10))
    print('start',start,'| L1:',repr(c[0]),'| L3:',repr(c[2]),'| L30:',repr(c[29]))
