/* nnn - the unorthodox terminal file manager (reimplementation) */
#include "nnn.h"

static const char *g_progname = "nnn";

/* ---- global state ---- */
static struct entry *g_dents;
static int g_ndents, g_cap;
static char g_path[PATH_MAXLEN];       /* current dir */
static char g_lastdir[PATH_MAXLEN];    /* last dir ('-') */
static char g_initdir[PATH_MAXLEN];    /* initial dir ('@') */
static char g_marked[PATH_MAXLEN];     /* marked dir */
static char g_home[PATH_MAXLEN];
static int g_cur;                      /* cursor */
static int g_top;                      /* first visible entry */
static int g_ctx = 0;                  /* active context */
static int g_ctxvis;                   /* bitmask of visited contexts */
static struct ctx g_ctxs[NCONTEXTS];
static uchar g_hidden = 0, g_detail = 0;
static int g_sort = SORT_NAME;
static uchar g_rev = 0;
static uchar g_selmulti = 0;
static int g_filtermode = FILTER_STR;
static char g_filter[NAME_MAXLEN];
static uchar g_filteractive = 0;
static uchar g_filterprompt = 0;
static uchar g_mark = 0;
static int g_nsel;
static uchar g_regfilter = 0, g_fzyfilter = 0, g_icase = 1, g_autoenter = 1;
static uchar g_type2nav = 0;
static char *g_pickfile = NULL;
static uchar g_quitconf = 1;
static char *g_sels;                   /* selection buffer */
static size_t g_selsz;
static char *g_session = NULL;
static uchar g_persist = 0;
static int g_scrolllines = 1;
static uchar g_showusers = 0;
static uchar g_rollover = 1;
static uchar g_advcp = 0;
static uchar g_nullsep = 0;
static char *g_opener = NULL;
static uchar g_ducurrent = 0;          /* disk usage mode: 1=apparent 2=blocks */
static off_t g_dutotal;
static blkcnt_t g_dublocks;
static off_t g_dufree;
static int g_dufiles;
static off_t g_blksz;
static char g_msg[512];
static int g_msgshow;
static uchar g_keycollide = 0;

#define SELECTION_BUFSZ (1 << 16)
#define MAXSelectors 512
static char *g_selpaths[MAXSelectors];
static int g_nselpts;

static char *g_editor = NULL;
static char *g_visual = NULL;

/* ---- helpers ---- */
static void die(const char *fmt, ...)
{
	va_list ap;
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	fputc('\n', stderr);
}

static void xmsg(const char *s) { xstrlcpy(g_msg, s, sizeof(g_msg)); g_msgshow = 1; }

static void xclearmsg(void) { g_msg[0] = '\0'; g_msgshow = 0; }

static int xisdir(const char *p)
{
	struct stat s;
	return !stat(p, &s) && S_ISDIR(s.st_mode);
}

static int xmkpath(const char *p, mode_t mode)
{
	char *tmp = xstrdup(p), *s;
	int r = 0;
	if (!tmp) return -1;
	for (s = tmp + 1; *s; ++s) {
		if (*s == '/') {
			*s = '\0';
			if (!xisdir(tmp) && mkdir(tmp, mode) == -1 && errno != EEXIST) { r = -1; break; }
			*s = '/';
		}
	}
	if (r == 0 && !xisdir(tmp) && mkdir(tmp, mode) == -1 && errno != EEXIST) r = -1;
	free(tmp);
	return r;
}

static int cmpname(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	return strcasecmp(a->name, b->name);
}

static int cmpver(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	const char *x = a->name, *y = b->name;
	while (*x && *y) {
		if (isdigit((uchar)*x) && isdigit((uchar)*y)) {
			long nx = 0, ny = 0;
			while (*x == '0') ++x;
			while (*y == '0') ++y;
			while (isdigit((uchar)*x)) { nx = nx * 10 + (*x - '0'); ++x; }
			while (isdigit((uchar)*y)) { ny = ny * 10 + (*y - '0'); ++y; }
			if (nx != ny) return nx > ny ? 1 : -1;
			continue;
		}
		if (*x != *y) break;
		++x; ++y;
	}
	if (!*x && !*y) return strcasecmp(a->name, b->name);
	return strcasecmp(x, y);
}

static const char *getext(const char *name)
{
	const char *p = strrchr(name, '.');
	return p ? p : name + strlen(name);
}

static int cmpext(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	int r = strcasecmp(getext(a->name), getext(b->name));
	if (r) return r;
	return strcasecmp(a->name, b->name);
}

static int cmpsize(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	off_t x = g_ducurrent ? a->size : a->size, y = b->size;
	if (x != y) return x > y ? -1 : 1;
	return strcasecmp(a->name, b->name);
}

static int cmptime(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	if (a->mt != b->mt) return a->mt > b->mt ? -1 : 1;
	return strcasecmp(a->name, b->name);
}

static int cmpdirs(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	int ad = a->type == DT_DIR, bd = b->type == DT_DIR;
	if (ad != bd) return ad ? -1 : 1;
	return 0;
}
CEOF
echo written; wc -l /workspace/src/nnn.c"}

