static int cmpgeneric(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	int ad = a->type == DT_DIR, bd = b->type == DT_DIR;
	if (ad != bd) return ad ? -1 : 1;
	if (a->blk != b->blk) return a->blk > b->blk ? -1 : 1;
	return strcasecmp(a->name, b->name);
}

static void sortents(void)
{
	if (g_dumode) { qsort(g_dents, g_ndents, sizeof(struct entry), cmpgeneric); return; }
	switch (g_sort) {
	case SORT_NAME: qsort(g_dents, g_ndents, sizeof(struct entry), cmpname); break;
	case SORT_EXT:  qsort(g_dents, g_ndents, sizeof(struct entry), cmpext); break;
	case SORT_SIZE: qsort(g_dents, g_ndents, sizeof(struct entry), cmpsize); break;
	case SORT_TIME: qsort(g_dents, g_ndents, sizeof(struct entry), cmptime); break;
	case SORT_VER:  qsort(g_dents, g_ndents, sizeof(struct entry), cmpver); break;
	}
	if (g_rev) {
		int i, j;
		/* reverse only within the same directory-ness group */
		for (i = 0, j = g_ndents - 1; i < j; ) {
			struct entry t = g_dents[i];
			g_dents[i] = g_dents[j];
			g_dents[j] = t;
			++i; --j;
		}
	}
