/* ---------------- size formatting ---------------- */
static void fmtsize(char *buf, size_t n, off_t sz)
{
	static const char units[] = "BKMGT";
	off_t v = sz, rem = 0;
	int unit = 0, dec;
	while (v >= 1024 && unit < 4) { rem = v % 1024; v /= 1024; ++unit; }
	if (unit == 0) { snprintf(buf, n, "%lldB", (long long)v); return; }
	dec = (int)((rem * 10 + 512) / 1024);
	if (dec >= 10) { ++v; dec = 0; }
	if (dec) snprintf(buf, n, "%lld.%d%c", (long long)v, dec, units[unit]);
	else snprintf(buf, n, "%lld%c", (long long)v, units[unit]);
}

/* ---------------- sorting ---------------- */
static const char *getext(const char *name)
{
	const char *p = strrchr(name, '.');
