}

static int cmpname(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	return strcasecmp(a->name, b->name);
}

static int cmpver(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	const char *x = a->name, *y = b->name;
	while (*x && *y) {
		if (isdigit((uchar)*x) && isdigit((uchar)*y)) {
			long nx = 0, ny = 0;
			while (*x == '0') ++x;
			while (*y == '0') ++y;
			while (isdigit((uchar)*x)) { nx = nx * 10 + (*x - '0'); ++x; }
			while (isdigit((uchar)*y)) { ny = ny * 10 + (*y - '0'); ++y; }
			if (nx != ny) return nx > ny ? 1 : -1;
			continue;
		}
		if (*x != *y) break;
		++x; ++y;
	}
	if (!*x && !*y) return 0;
