}

static int cmpgeneric(const void *pa, const void *pb)
{
	const struct entry *a = pa, *b = pb;
	int ad = a->type == DT_DIR, bd = b->type == DT_DIR;
	if (ad != bd) return ad ? -1 : 1;
	if (a->blk != b->blk) return a->blk > b->blk ? -1 : 1;
	return strcasecmp(a->name, b->name);
}

