/* ---------------- directory reading ---------------- */
static void frees(void)
{
	int i;
	for (i = 0; i < g_ndents; ++i) free(g_dents[i].name);
	g_ndents = 0;
}

static void addent(const char *name, const struct stat *ps, uchar type)
{
	struct entry *e;
	if (g_ndents >= g_cap) {
		int nc = g_cap ? g_cap * 2 : 256;
		g_dents = realloc(g_dents, nc * sizeof(struct entry));
		if (!g_dents) die("malloc!");
		g_cap = nc;
	}
	e = &g_dents[g_ndents++];
	e->name = xstrdup(name);
	e->size = ps->st_size;
	e->blk = (off_t)ps->st_blocks * 512;
	e->blocks = ps->st_blocks;
	e->mt = ps->st_mtime;
	e->mode = ps->st_mode & 07777;
	e->uid = ps->st_uid;
	e->gid = ps->st_gid;
	e->type = type;
	e->sel = 0;
	e->rsize = e->size;
	e->rblk = e->blk;
}

static void recalcs(int idx)
{
	/* recursive size for dirs */
	struct entry *e = &g_dents[idx];
	if (e->type != DT_DIR) { e->rsize = e->size; e->rblk = e->blk; return; }
	{
		char p[PATH_MAXLEN], sub[PATH_MAXLEN];
		DIR *d;
		struct dirent *de;
		off_t ts = 0, tb = 0;
		snprintf(p, sizeof(p), "%s/%s", g_path, e->name);
		d = opendir(p);
		if (d) {
			while ((de = readdir(d))) {
				struct stat st;
				if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
				snprintf(sub, sizeof(sub), "%s/%s", p, de->d_name);
				if (lstat(sub, &st) == -1) continue;
				if (S_ISDIR(st.st_mode)) {
					char op[PATH_MAXLEN];
					off_t a, b;
					xstrlcpy(op, g_path, sizeof(op));
					xstrlcpy(g_path, p, sizeof(g_path));
					/* recurse via a temp entry */
					{
						struct entry tmp;
						memset(&tmp, 0, sizeof(tmp));
						tmp.name = xstrdup(de->d_name);
						tmp.size = st.st_size; tmp.blk = (off_t)st.st_blocks * 512;
						tmp.type = DT_DIR; tmp.rsize = 0; tmp.rblk = 0;
						/* simple recursion */
						a = st.st_size; b = (off_t)st.st_blocks * 512;
						{
							DIR *d2 = opendir(sub);
							struct dirent *de2;
							if (d2) {
								while ((de2 = readdir(d2))) {
									struct stat st2;
									char sub2[PATH_MAXLEN];
									if (!strcmp(de2->d_name, ".") || !strcmp(de2->d_name, "..")) continue;
									snprintf(sub2, sizeof(sub2), "%s/%s", sub, de2->d_name);
									if (stat(sub2, &st2) == -1) continue;
									if (S_ISDIR(st2.st_mode)) {
										off_t c = 0, dd = 0;
										char sub3[PATH_MAXLEN];
										DIR *d3 = opendir(sub2);
										struct dirent *de3;
										snprintf(sub3, sizeof(sub3), "%s", sub2);
										if (d3) {
											while ((de3 = readdir(d3))) {
												struct stat st3;
												char sub4[PATH_MAXLEN];
												if (!strcmp(de3->d_name, ".") || !strcmp(de3->d_name, "..")) continue;
												snprintf(sub4, sizeof(sub4), "%s/%s", sub3, de3->d_name);
												if (lstat(sub4, &st3) == -1) continue;
												c += st3.st_size; dd += (off_t)st3.st_blocks * 512;
											}
											closedir(d3);
										}
										c += st2.st_size; dd += (off_t)st2.st_blocks * 512;
										a += c; b += dd;
									} else { a += st2.st_size; b += (off_t)st2.st_blocks * 512; }
								}
								closedir(d2);
							}
						}
						a += st.st_size; b += (off_t)st.st_blocks * 512;
						free(tmp.name);
						ts += a; tb += b;
					}
				} else { ts += st.st_size; tb += (off_t)st.st_blocks * 512; }
			}
			closedir(d);
		}
		e->rsize = ts;
		e->rblk = tb;
	}
}

static int filtered(const char *name)
{
	if (!g_filteractive || !g_filter[0]) return 1;
	if (g_regfilter) {
		regex_t re;
		int r;
		char buf[NAME_MAXLEN];
		xstrlcpy(buf, g_filter, sizeof(buf));
		if (regcompwrap(&re, buf, g_icase ? REG_ICASE | REG_NOSUB : REG_NOSUB) != 0) return 1;
		r = regexec(&re, name) == 0;
		regfree(&re);
		return r;
	}
	if (g_fzyfilter) return fzmatch(name, g_filter);
	return icontains(name, g_filter, g_icase);
}

static int browsedir(const char *path)
{
	DIR *d;
	struct dirent *de;
	struct stat st;
	char full[PATH_MAXLEN];
	int i;

	frees();
	if (!(d = opendir(path))) { g_ndents = 0; return -1; }
	while ((de = readdir(d))) {
		if (!g_hidden && de->d_name[0] == '.') continue;
		if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
		snprintf(full, sizeof(full), "%s/%s", path, de->d_name);
		if (lstat(full, &st) == -1) continue;
		switch (st.st_mode & S_IFMT) {
		case S_IFDIR: addent(de->d_name, &st, DT_DIR); break;
		case S_IFREG: addent(de->d_name, &st, DT_REG); break;
		case S_IFLNK: addent(de->d_name, &st, DT_LNK); break;
		case S_IFIFO: addent(de->d_name, &st, DT_FIFO); break;
		case S_IFSOCK: addent(de->d_name, &st, DT_SOCK); break;
		case S_IFCHR: addent(de->d_name, &st, DT_CHR); break;
		case S_IFBLK: addent(de->d_name, &st, DT_BLK); break;
		default: addent(de->d_name, &st, DT_REG); break;
		}
	}
	closedir(d);
	/* keep the selection marks */
	for (i = 0; i < g_ndents; ++i) {
		int j;
		for (j = 0; j < g_nselpts; ++j)
			if (!strcmp(g_selpaths[j], g_path) || !strcmp(g_selnames[j], g_dents[i].name)) break;
		(void)j;
	}
	/* compute disk usage stats */
	g_dutotal = 0; g_dublocks = 0; g_dufiles = 0;
	for (i = 0; i < g_ndents; ++i) recalcs(i);
	for (i = 0; i < g_ndents; ++i) {
		if (g_dumode == 1) g_dutotal += g_dents[i].rsize;
		else g_dutotal += g_dents[i].rblk;
		if (g_dents[i].type != DT_DIR) ++g_dufiles;
	}
	{
		struct statvfs sv;
		if (statvfs(path, &sv) != -1) g_dufree = (off_t)sv.f_bavail * sv.f_frsize;
		else g_dufree = 0;
		g_blksz = sv.f_bsize;
	}
	sortents();
	return g_ndents;
}
CEOF
echo ok; wc -l /workspace/src/nnn.c"}

