		++s; ++p;
	}
	return 1;
}

static int regcompwrap(regex_t *re, const char *pat, int flags)
{
	return regcomp(re, pat, flags);
}

static int regexecwrap(const regex_t *re, const char *s)
{
	return regexec(re, s, 0, NULL, 0);
}

/* ---------------- selection ---------------- */
static int selpath(const char *name, char *buf, size_t n)
{
	snprintf(buf, n, "%s/%s", g_path, name);
	return 0;
}

static void seltoggle(int idx)
{
	char p[PATH_MAXLEN];
	int i;
	struct entry *e = &g_dents[idx];
	selpath(e->name, p, sizeof(p));
	for (i = 0; i < g_nselpts; ++i) if (!strcmp(g_selpaths[i], p)) break;
	if (i < g_nselpts) {
		for (; i < g_nselpts - 1; ++i) {
			xstrlcpy(g_selpaths[i], g_selpaths[i + 1], PATH_MAXLEN);
			xstrlcpy(g_selnames[i], g_selnames[i + 1], NAME_MAXLEN);
		}
		--g_nselpts;
		e->sel = 0;
	} else {
		if (g_nselpts < MAXSEL) {
			xstrlcpy(g_selpaths[g_nselpts], p, PATH_MAXLEN);
			xstrlcpy(g_selnames[g_nselpts], e->name, NAME_MAXLEN);
			++g_nselpts;
			e->sel = 1;
		}
	}
	if (e->sel) ++g_nsel; else if (g_nsel > 0) --g_nsel;
}

static void refreshsel(void)
{
	int i;
	for (i = 0; i < g_ndents; ++i) {
		char p[PATH_MAXLEN];
		int j;
		selpath(g_dents[i].name, p, sizeof(p));
		for (j = 0; j < g_nselpts; ++j) if (!strcmp(g_selpaths[j], p)) break;
		g_dents[i].sel = (j < g_nselpts);
	}
}

static void selall(void)
{
	int i;
	for (i = 0; i < g_ndents; ++i) {
		char p[PATH_MAXLEN];
		int j;
		selpath(g_dents[i].name, p, sizeof(p));
		for (j = 0; j < g_nselpts; ++j) if (!strcmp(g_selpaths[j], p)) break;
		if (j == g_nselpts && g_nselpts < MAXSEL) {
			xstrlcpy(g_selpaths[g_nselpts], p, PATH_MAXLEN);
			xstrlcpy(g_selnames[g_nselpts], g_dents[i].name, NAME_MAXLEN);
			++g_nselpts;
		}
	}
	refreshsel();
	g_nsel = 0;
	for (i = 0; i < g_nselpts; ++i) ++g_nsel;
}

static void selclear(void)
{
	g_nselpts = 0;
	refreshsel();
	g_nsel = 0;
}

static void selsizeoff(void)
{
	int i;
	off_t t = 0;
	for (i = 0; i < g_nselpts; ++i) {
		struct stat st;
		if (stat(g_selpaths[i], &st) != -1) t += st.st_size;
	}
	{
		char b[64];
		fmtsize(b, sizeof(b), t);
		xmsg(b);
	}
}

