static void setcolor(int c, uchar bold, uchar dim, uchar rev, uchar ul)
{
	attr_t a = 0;
	if (bold) a |= A_BOLD;
	if (dim) a |= A_DIM;
	if (rev) a |= A_REVERSE;
	if (ul) a |= A_UNDERLINE;
	(void)c;
	attrset(a | COLOR_PAIR(c));
}
