/* ---------------- display path ---------------- */
static const char *disppath(void)
{
	static char buf[PATH_MAXLEN];
	if (g_home[0] && !strncmp(g_path, g_home, strlen(g_home))) {
		snprintf(buf, sizeof(buf), "~%s", g_path + strlen(g_home));
		return buf;
	}
	return g_path;
}

/* ---------------- rendering ---------------- */
static void drawrow(int idx, int row)
{
	struct entry *e = &g_dents[idx];
	char buf[PATH_MAXLEN];
	char sz[16], date[32], perms[8];
	uchar iscur = idx == g_cur;
	char ind = e->sel ? '+' : ' ';
	char suf = entrysuffix(e);
	int col = 0;

	move(row, 0);
	if (g_detail) {
		/* cursor column + date + perms + size */
		int ec = e->type == DT_DIR ? CLR_DIR : (e->type == DT_LNK ? CLR_LINK : CLR_BAR);
		setcolor(ec, 0, 0, 0, 0);
		addch(iscur ? '>' : ' ');
		if (iscur) attron(A_BOLD);
		attroff(A_REVERSE);
		attron(A_DIM);
		setcolor(ec, 0, 1, 0, 0);
		fmtdate(e, date, sizeof(date));
		addstr(date);
		attroff(A_REVERSE);
		setcolor(ec, iscur, 1, 0, 0);
		fmtperms(e, perms, sizeof(perms));
		fmtsize(sz, sizeof(sz), g_dumode == 2 ? e->blk : e->size);
		snprintf(buf, sizeof(buf), "  %-3s%9s ", perms, sz);
		addstr(buf);
		attroff(A_DIM);
		if (iscur) attron(A_REVERSE);
		setcolor(ec, 0, 0, 0, 0);
	} else {
		int ec = e->type == DT_DIR ? CLR_DIR : (e->type == DT_LNK ? CLR_LINK : CLR_BAR);
		setcolor(ec, 0, 0, 0, 0);
	}

	/* indicator */
	setcolor(e->type == DT_DIR ? CLR_DIR : CLR_BAR, 0, 0, 0, 0);
	addch(ind);

	if (iscur) {
		attron(A_BOLD);
		attron(A_REVERSE);
	}

	/* name with type colour */
	{
		int ec = e->type == DT_DIR ? CLR_DIR : (e->type == DT_LNK ? CLR_LINK : CLR_BAR);
		setcolor(ec, 0, 0, 0, 0);
	}
	snprintf(buf, sizeof(buf), "%.*s", g_cols - col - 4, e->name);
	addstr(buf);
	if (iscur) attroff(A_REVERSE);
	setcolor(e->type == DT_DIR ? CLR_DIR : CLR_BAR, 0, 0, 0, 0);
	if (suf) addch(suf);
	attroff(A_BOLD);
	setcolor(CLR_BAR, 0, 0, 0, 0);
}

static void drawheader(void)
{
	int i;
	char buf[PATH_MAXLEN];
	move(0, 0);
	clrtoeol();
	for (i = 0; i < NCONTEXTS; ++i) {
		int act = i == g_ctx;
		if (act) setcolor(CLR_DIR, 1, 0, 1, 0);
		else if (g_ctxs[i].visited) setcolor(CLR_DIR, 1, 0, 0, 1);
		else setcolor(CLR_BAR, 0, 0, 0, 0);
		addch('0' + i + 1);
		addch(' ');
	}
	setcolor(CLR_DIR, 0, 0, 0, 1);
	snprintf(buf, sizeof(buf), "%.*s", g_cols - NCONTEXTS * 2, disppath());
	addstr(buf);
	setcolor(CLR_BAR, 0, 0, 0, 0);
}

static void drawstatus(void)
{
	char buf[1024];
	struct entry *e = g_ndents ? &g_dents[g_cur] : NULL;
	char sz[32], date[32], perms[8], ext[NAME_MAXLEN];
	int pos = 0;
	int flags;

	move(g_rows - 1, 0);
	clrtoeol();
	setcolor(CLR_DIR, 0, 0, 0, 0);
	if (g_msgshow) {
		addstr(g_msg);
		setcolor(CLR_BAR, 0, 0, 0, 0);
		return;
	}
	pos = snprintf(buf, sizeof(buf), "%d/%d ", g_ndents ? g_cur + 1 : 0, g_ndents);
	addstr(buf);
	if (g_nselpts) {
		char f[16];
		snprintf(f, sizeof(f), "%s%d", g_mark ? "*" : "+", g_nselpts);
		setcolor(CLR_DIR, 0, 0, 1, 0);
		pos += snprintf(buf, sizeof(buf), " %s ", f);
		addstr(buf);
		setcolor(CLR_DIR, 0, 0, 0, 0);
	} else if (g_mark) {
		setcolor(CLR_DIR, 0, 0, 1, 0);
		addstr(" * ");
		setcolor(CLR_DIR, 0, 0, 0, 0);
	}
	addstr(" ");
	flags = 0;
	if (g_hidden) addch('H');
	if (g_sort == SORT_EXT) addch('E');
	if (g_sort == SORT_SIZE) addch('S');
	if (g_sort == SORT_TIME) addch('M');
	if (g_sort == SORT_VER) addch('V');
	if (g_rev) addch('R');
	addstr(" ");
	if (!e) { setcolor(CLR_BAR, 0, 0, 0, 0); return; }

	if (g_dumode) {
		char tot[32], free_[32], cursz[32];
		fmtsize(tot, sizeof(tot), g_dutotal);
		fmtsize(free_, sizeof(free_), g_dufree);
		if (g_dumode == 1) snprintf(cursz, sizeof(cursz), "%lldB", (long long)e->rsize);
		else snprintf(cursz, sizeof(cursz), "%lldB", (long long)e->rblk);
		snprintf(buf, sizeof(buf), "%s:%s avail:%s files:%d %s",
		         g_dumode == 1 ? "au" : "du", tot, free_, g_dufiles, cursz);
		addstr(buf);
		setcolor(CLR_BAR, 0, 0, 0, 0);
		return;
	}
	fmtdate(e, date, sizeof(date));
	setcolor(CLR_DIR, 0, 0, 1, 0);
	addstr(date);
	attroff(A_REVERSE);
	setcolor(CLR_DIR, 0, 0, 0, 0);
	fmtperms(e, perms, sizeof(perms));
	fmtsize(sz, sizeof(sz), e->size);
	pos = 0;
	pos += snprintf(buf + pos, sizeof(buf) - pos, " %s %s", perms, sz);
	if (g_showusers) {
		struct passwd *pw = getpwuid(e->uid);
		struct group *gr = getgrgid(e->gid);
		pos += snprintf(buf + pos, sizeof(buf) - pos, " %s:%s", pw ? pw->pw_name : "", gr ? gr->gr_name : "");
	}
	setcolor(CLR_DIR, 0, 0, 0, 0);
	addstr(buf);
	{
		const char *x = strrchr(e->name, '.');
		if (x && x != e->name) {
			char b[NAME_MAXLEN];
			snprintf(b, sizeof(b), " %s", x);
			addstr(b);
		}
	}
	if (e->nlink > 1) {
		char b[64];
		snprintf(b, sizeof(b), " %u-%lu", e->nlink, (unsigned long)e->ino);
		addstr(b);
	}
	setcolor(CLR_BAR, 0, 0, 0, 0);
}

static void draw(void)
{
	clear();
	drawheader();
	drawlist();
	refresh();
}
