/* ---------------- prompts ---------------- */
static int readstr(const char *prompt, char *buf, size_t n, const char *init)
{
	int len = 0, cur = 0, c;
	char hint[128];
	if (init) { xstrlcpy(buf, init, n); len = cur = strlen(buf); } else buf[0] = '\0';
	g_filterprompt = 0;
	for (;;) {
		move(g_rows - 1, 0);
		clrtoeol();
		if (prompt) addstr(prompt);
		addstr(buf);
		refresh();
		c = getch();
		if (c == '\r' || c == '\n' || c == KEY_ENTER) return 1;
		if (c == KEY_BACKSPACE || c == 127 || c == 8) {
			if (cur > 0) {
				memmove(buf + cur - 1, buf + cur, len - cur + 1);
				--cur; --len;
			}
			continue;
		}
		if (c == KEY_LEFT) { if (cur) --cur; continue; }
		if (c == KEY_RIGHT) { if (cur < len) ++cur; continue; }
		if (c == 27) { buf[0] = '\0'; return 0; }
		if (c == 4 || c == 26) return 0;
		if (c >= 32 && c < 127) {
			if (len < (int)n - 1) {
				memmove(buf + cur + 1, buf + cur, len - cur + 1);
				buf[cur] = c; ++cur; ++len;
			}
			continue;
		}
	}
	(void)hint;
}

