	for (;;) {
		move(g_rows - 2, 0);
		clrtoeol();
		{
			char h[64];
			snprintf(h, sizeof(h), "%s [%c], ic [%c]:", mode, pre, g_icase ? ':' : 'i');
			mvprintw(g_rows - 2, g_cols - strlen(h) - 2, "  %s", h);
		}
		move(g_rows - 1, 0);
		clrtoeol();
		addch(pre);
		addstr(buf);
		refresh();
		c = getch();
		g_filterprompt = 0;
		if (c == '\r' || c == '\n' || c == KEY_ENTER) { g_filterprompt = 0; return 1; }
		g_filterprompt = 1;
