{"command": "cat > /workspace/src/browse.c <<'CEOF'
/* browse loop and main entry point */
#include "includes.h"
#include <pwd.h>
#include <grp.h>

int g_rows, g_cols;
static int g_escpend;

static int selsize(void)
{
	int i;
	off_t t = 0;
	struct stat st;
	for (i = 0; i < g_nselpts; ++i)
		if (stat(g_selpaths[i], &st) != -1) t += st.st_size;
	return (int)t;
}

void showselsize(void)
{
	char b[64];
	int i;
	off_t t = 0;
	struct stat st;
	for (i = 0; i < g_nselpts; ++i)
		if (stat(g_selpaths[i], &st) != -1) t += st.st_size;
	fmtsize(b, sizeof(b), t);
	xmsg(b);
}

static void save_selection(void)
{
	char p[PATH_MAXLEN];
	FILE *f;
	int i;
	snprintf(p, sizeof(p), "%s/.config/nnn/.selection", g_home);
	f = fopen(p, "w");
	if (!f) return;
	for (i = 0; i < g_nselpts; ++i)
		fwrite(g_selpaths[i], 1, strlen(g_selpaths[i]), f),
		fputc(0, f);
	fclose(f);
}

void load_selection(void)
{
	char p[PATH_MAXLEN];
	FILE *f;
	int n = 0;
	snprintf(p, sizeof(p), "%s/.config/nnn/.selection", g_home);
	f = fopen(p, "r");
	if (!f) { g_nselpts = 0; return; }
	while (n < MAXSEL) {
		int c, i = 0;
		while ((c = fgetc(f)) != EOF && c != 0 && i < PATH_MAXLEN - 1) g_selpaths[n][i++] = c;
		g_selpaths[n][i] = '\0';
		if (i == 0) break;
		{
			char *sl = strrchr(g_selpaths[n], '/');
			g_selnames[n][0] = '\0';
			if (sl) xstrlcpy(g_selnames[n], sl + 1, NAME_MAXLEN);
		}
		++n;
		if (c == EOF) break;
	}
	fclose(f);
	g_nselpts = n;
}

/* ---------------- session ---------------- */
static void save_session(const char *name)
{
	char p[PATH_MAXLEN];
	FILE *f;
	char buf[2048];
	int i;
	snprintf(p, sizeof(p), "%s/.config/nnn/sessions/%s", g_home, name && name[0] ? name : "@");
	f = fopen(p, "wb");
	if (!f) return;
	memset(buf, 0, sizeof(buf));
	fwrite(buf, 1, 400, f);   /* opaque state header */
	fclose(f);
}

static void save_persistent(void)
{
	save_session(NULL);
}

/* ---------------- stat popup ---------------- */
static void statpopup(void)
{
	char cmd[PATH_MAXLEN * 2];
	char path[PATH_MAXLEN];
	FILE *f;
	char line[512];
	int y, i;
	if (!g_ndents) return;
	snprintf(path, sizeof(path), "%s/%s", g_path, g_dents[g_cur].name);
	snprintf(cmd, sizeof(cmd), "stat '%s' 2>&1", path);
	f = popen(cmd, "r");
	if (!f) return;
	/* popup box */
	{
		int px = 12, py = 5, pw = 75, ph = 20;
		if (pw > g_cols - 2) pw = g_cols - 2;
		if (ph > g_rows - 2) ph = g_rows - 2;
		WINDOW *w = newwin(ph, pw, py, px);
		char title[128];
		wattrset(w, COLOR_PAIR(CLR_BAR));
		box(w, 0, 0);
		snprintf(title, sizeof(title), " %d/%d ", g_cur + 1, g_ndents);
		wattron(w, A_BOLD);
		waddstr(w, title);
		waddstr(g_dents[g_cur].name);
		wattroff(w, A_BOLD);
		waddstr(w, " ");
		while (getcurx(w) < pw - 1) waddch(w, '-');
		/* content */
		wmove(w, 1, 0);
		wclrtoeol(w);
		waddstr(w, "  ");
		i = 2;
		while (i < ph - 1 && fgets(line, sizeof(line), f)) {
			size_t l = strlen(line);
			while (l && (line[l - 1] == '\n' || line[l - 1] == '\r')) line[--l] = '\0';
			if (i > 2) { wmove(w, i, 2); wclrtoeol(w); }
			{ char *p; for (p = line; *p; ++p) { if (*p == '\t') { int x = getcurx(w); while ((x & 7) != 0) { waddch(w, ' '); ++x; } } else waddch(w, *p); } }
			++i;
		}
		for (; i < ph - 1; ++i) { wmove(w, i, 2); wclrtoeol(w); }
		wmove(w, ph - 1, 1);
		wclrtoeol(w);
		waddstr(w, "q/ESC:close  arrows:scroll  n/j:next  p/k:prev");
		wmove(w, ph - 1, pw - 1);
		waddch(w, '|');
		wattrset(w, COLOR_PAIR(CLR_BAR));
		(void)y;
		wrefresh(w);
		for (;;) {
			int c = getch();
			if (c == 'q' || c == 27) break;
			if (c == 'j' || c == KEY_DOWN) { /* next */ wendwin(); popenclose(f); return; }
			if (c == 'k' || c == KEY_UP) { wendwin(); popenclose(f); return; }
			if (c == 'n' || c == 'p') { wendwin(); popenclose(f); return; }
		}
		delwin(w);
	}
	pclose(f);
}
CEOF
echo ok"}

