/* ---------------- sort prompt ---------------- */
static void sortprompt(int timeonly)
{
	int c;
	if (timeonly) {
		c = askchoice("'a'ccess / 'c'hange / 'm'od [m]", "acm");
		if (c < 0) return;
		g_sort = SORT_TIME;
		switch (c) {
		case 'a': g_timekey = 0; break;
		case 'c': g_timekey = 1; break;
		case 'm': g_timekey = 2; break;
		}
		g_dumode = 0;
		sortents();
		return;
	}
	c = askchoice("'a'u/'d'u/'e'xt/'r'ev/'s'z/'t'm/'v'er/'c'lr/'^T'?", "adersvtc\024");
	switch (c) {
	case 'a': g_dumode = 1; break;
	case 'd': g_dumode = 2; break;
	case 'e': g_dumode = 0; g_sort = SORT_EXT; break;
	case 'r': g_rev = !g_rev; g_dumode = 0; break;
	case 's': g_dumode = 0; g_sort = SORT_SIZE; break;
	case 't': g_dumode = 0; g_sort = SORT_TIME; break;
	case 'v': g_dumode = 0; g_sort = SORT_VER; break;
	case 'c': g_dumode = 0; g_sort = SORT_NAME; g_rev = 0; break;
	default: return;
	}
	sortents();
}

/* ---------------- rename / misc prompts ---------------- */
static void newentry(int kind)
{
	char name[NAME_MAXLEN];
	char full[PATH_MAXLEN];
	struct stat st;
	int r;
	if (!readstr("[path/]name:", name, sizeof(name), NULL)) return;
	if (!name[0]) { xmsg("cancelled"); return; }
	snprintf(full, sizeof(full), "%s/%s", g_path, name);
	switch (kind) {
	case 'f':
		if (stat(full, &st) != -1) { xmsg("failed!"); return; }
		r = open(full, O_CREAT | O_EXCL | O_WRONLY, 0600);
		if (r < 0) { xmsg("failed!"); return; }
		close(r);
		break;
	case 'd':
		if (mkdir(full, 0755) == -1) { xmsg("failed!"); return; }
		break;
	case 's':
		if (g_ndents) {
			char tgt[PATH_MAXLEN];
			snprintf(tgt, sizeof(tgt), "%s/%s", g_path, g_dents[g_cur].name);
			if (symlink(tgt, full) == -1) { xmsg("failed!"); return; }
		}
		break;
	case 'h':
		if (g_ndents) {
			char tgt[PATH_MAXLEN];
			snprintf(tgt, sizeof(tgt), "%s/%s", g_path, g_dents[g_cur].name);
			if (link(tgt, full) == -1) { xmsg("failed!"); return; }
		}
		break;
	}
	browsedir(g_path);
	refreshsel();
}

static void deleteentry(void)
{
	char path[PATH_MAXLEN];
	char msg[PATH_MAXLEN + 64];
	int c;
	if (g_nselpts) {
		c = askchoice("'c'urrent/'s'el?", "cs");
		if (c < 0) return;
		if (c == 's') {
			snprintf(msg, sizeof(msg), "rm -rf %d file(s)?", g_nselpts);
			if (!askconfirm(msg)) return;
			op_deleteall();
			selclear();
			save_selection();
			browsedir(g_path);
			refreshsel();
			return;
		}
	}
	if (!g_ndents) return;
	snprintf(path, sizeof(path), "%s/%s", g_path, g_dents[g_cur].name);
	snprintf(msg, sizeof(msg), "rm -rf '%s'?", g_dents[g_cur].name);
	if (!askconfirm(msg)) return;
	op_delete(path);
	{
		int i;
		char ab[PATH_MAXLEN];
		for (i = 0; i < g_nselpts; ++i) if (!strcmp(g_selpaths[i], path)) break;
		if (i < g_nselpts) {
			for (; i < g_nselpts - 1; ++i) { xstrlcpy(g_selpaths[i], g_selpaths[i+1], PATH_MAXLEN); xstrlcpy(g_selnames[i], g_selnames[i+1], NAME_MAXLEN); }
			--g_nselpts;
			save_selection();
		}
	}
	browsedir(g_path);
	refreshsel();
}

static void archiveentry(void)
{
	char name[NAME_MAXLEN];
	const char *init = g_ndents ? g_dents[g_cur].name : "";
	if (!readstr("archive [path/]name:", name, sizeof(name), init)) return;
	if (!name[0]) return;
	op_archive(name);
	browsedir(g_path);
	refreshsel();
}

static void remoteentry(void)
{
	char name[NAME_MAXLEN];
	if (!readstr("remote name (- for hovered):", name, sizeof(name), NULL)) return;
	if (!name[0] || !strcmp(name, "-")) {
		if (g_ndents && g_dents[g_cur].type == DT_DIR) {
			char cmd[PATH_MAXLEN * 2];
			snprintf(cmd, sizeof(cmd), "rmdir '%s'", g_dents[g_cur].name);
			runcmd(cmd, NULL, NULL);
		}
	} else {
		char p[PATH_MAXLEN];
		snprintf(p, sizeof(p), "%s/.config/nnn/mounts/%s", g_home, name);
		if (!xisdir(p)) {
			char cmd[PATH_MAXLEN * 2];
			snprintf(cmd, sizeof(cmd), "mkdir -p '%s'", p);
			runcmd(cmd, NULL, NULL);
		}
	}
	browsedir(g_path);
	refreshsel();
}

static void mountremote(void)
{
	DIR *d;
	struct dirent *de;
	char p[PATH_MAXLEN];
	snprintf(p, sizeof(p), "%s/.config/nnn/mounts", g_home);
	d = opendir(p);
	if (d) {
		int any = 0;
		while ((de = readdir(d))) {
			char full[PATH_MAXLEN];
			if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
			any = 1;
		}
		closedir(d);
		(void)any;
	}
	xmsg("install sshfs/rclone");
}

static void openwith(void)
{
	char app[NAME_MAXLEN];
	int c;
	endwin();
	clear();
	if (!readstr("open with:", app, sizeof(app), NULL)) { clear(); return; }
	if (!app[0]) { clear(); return; }
	c = askchoice("['g'ui]/'c'li?", "gc");
	clear();
	if (c < 0) return;
	if (g_ndents) {
		char full[PATH_MAXLEN];
		snprintf(full, sizeof(full), "%s/%s", g_path, g_dents[g_cur].name);
		openentry(full, app, c);
	}
}

static void runapp(void)
{
	char app[NAME_MAXLEN];
	endwin();
	clear();
	if (!readstr("app:", app, sizeof(app), NULL)) { clear(); return; }
	if (!app[0]) { clear(); return; }
	runcmd(app, NULL, NULL);
	clear();
}

static void copysmoveas(void)
{
	int c;
	c = askchoice("'c'p/'m'v as?", "cm");
	if (c < 0) return;
	op_paste(c == 'm');
	browsedir(g_path);
	refreshsel();
}

static void renamecurrent(void)
{
	op_renamebatch();
	browsedir(g_path);
	refreshsel();
}

static void jumprompt(void)
{
	char buf[NAME_MAXLEN];
	int n, i, c;
	if (!g_ndents) return;
	/* show relative offsets */
	move(g_rows - 1, 0);
	clrtoeol();
	if (!readstr("jump (+n/-n/n):", buf, sizeof(buf), NULL)) return;
	if (!buf[0]) return;
	{
		int rel = atoi(buf);
		if (buf[0] == '+') { n = g_cur + rel; }
		else if (buf[0] == '-') { n = g_cur - rel; }
		else n = rel;
	}
	if (n < 0) n = 0;
	if (n > g_ndents - 1) n = g_ndents - 1;
	g_cur = n;
	(void)i;
	(void)c;
}

static void sessionprompt(void)
{
	int c;
	char name[NAME_MAXLEN];
	c = askchoice("'s'ave/'l'oad/'r'estore?", "slr");
	if (c < 0) return;
	if (c == 's') {
		if (!readstr("session name:", name, sizeof(name), NULL)) return;
		if (!name[0]) { xmsg("cancelled"); return; }
		save_session(name);
	} else if (c == 'l') {
		if (!readstr("session name:", name, sizeof(name), NULL)) return;
		/* load */
		if (!name[0]) return;
		{
			char p[PATH_MAXLEN];
			FILE *f;
			snprintf(p, sizeof(p), "%s/.config/nnn/sessions/%s", g_home, name);
			f = fopen(p, "rb");
			if (!f) { xmsg("cancelled"); return; }
			{ char b[512]; fread(b, 1, sizeof(b), f); }
			fclose(f);
		}
	} else if (c == 'r') {
		setpath(g_initdir);
	}
}
