int g_timekey = 2;

/* ---------------- main browse loop ---------------- */
void browse(void)
{
	int c;

	for (;;) {
		draw();
		c = getch();
		xclrmsg();
		if (g_escpend) {
			g_escpend = 0;
			if (c == 27) { quitnnn(0); return; }
			/* a lone escape followed by another key: ignore the first */
			continue;
		}
		if (c == 27) { g_escpend = 1; continue; }
		switch (c) {
		case KEY_UP:
		case 'k':
			if (g_ndents) { if (g_cur > 0) --g_cur; else if (g_rollover) g_cur = g_ndents - 1; }
			break;
		case KEY_DOWN:
		case 'j':
			if (g_ndents) { if (g_cur + 1 < g_ndents) ++g_cur; else if (g_rollover) g_cur = 0; }
			break;
		case KEY_LEFT:
		case 'h': {
			char parent[PATH_MAXLEN];
			if (!strcmp(g_path, "/")) break;
			xdirname(g_path, parent, sizeof(parent));
			setpath(parent);
			break;
		}
		case KEY_RIGHT:
		case 'l':
		case '\r':
		case '\n':
		case KEY_ENTER:
			if (!g_ndents) break;
			if (g_dents[g_cur].type == DT_DIR) {
				char p[PATH_MAXLEN];
				snprintf(p, sizeof(p), "%s/%s", g_path, g_dents[g_cur].name);
				setpath(p);
			} else if (g_dents[g_cur].type == DT_LNK) {
				char p[PATH_MAXLEN], t[PATH_MAXLEN];
				snprintf(p, sizeof(p), "%s/%s", g_path, g_dents[g_cur].name);
				if (realpath(p, t)) {
					if (xisdir(t)) setpath(t);
					else editfile(p);
				} else xmsg("failed!");
			} else {
				char p[PATH_MAXLEN];
				snprintf(p, sizeof(p), "%s/%s", g_path, g_dents[g_cur].name);
				editfile(p);
			}
			break;
		case KEY_HOME:
		case 'g':
			if (g_ndents) g_cur = 0;
			break;
		case KEY_END:
		case 'G':
		case 5: /* ctrl-e */
			if (g_ndents) g_cur = g_ndents - 1;
			break;
		case KEY_PPAGE:
			if (g_ndents) g_cur = 0;
			break;
		case KEY_NPAGE:
			if (g_ndents) g_cur = g_ndents - 1;
			break;
		case 6: /* ctrl-f */
			statpopup();
			break;
		case 'f':
			statpopup();
			break;
		case '\t':
			cyclectx();
			break;
		case ' ':
			if (g_ndents) {
				seltoggle(g_cur);
				save_selection();
				if (!g_noadvance && g_cur + 1 < g_ndents) ++g_cur;
			}
			break;
		case 'a':
			selall();
			save_selection();
			break;
		case 'A':
			selclear();
			save_selection();
			break;
		case '+':
			if (g_ndents) { seltoggle(g_cur); save_selection(); if (g_cur + 1 < g_ndents) ++g_cur; }
			break;
		case 'd':
			g_detail = !g_detail;
			break;
		case '.':
			g_hidden = !g_hidden;
			browsedir(g_path);
			refreshsel();
			break;
		case 'm':
			if (g_rangemark_dir_ok()) {
				if (g_rangemark_set) {
					int a = g_rangemark, b = g_cur;
					int i;
					if (a > b) { int t = a; a = b; b = t; }
					selclear();
					for (i = a; i <= b; ++i) {
						char p[PATH_MAXLEN];
						int j;
						snprintf(p, sizeof(p), "%s/%s", g_path, g_dents[i].name);
						for (j = 0; j < g_nselpts; ++j) if (!strcmp(g_selpaths[j], p)) break;
						if (j == g_nselpts && g_nselpts < MAXSEL) {
							xstrlcpy(g_selpaths[g_nselpts], p, PATH_MAXLEN);
							xstrlcpy(g_selnames[g_nselpts], g_dents[i].name, NAME_MAXLEN);
							++g_nselpts;
						}
					}
					refreshsel();
					g_rangemark_set = 0;
					save_selection();
				} else {
					g_rangemark = g_cur;
					g_rangemark_set = 1;
					xstrlcpy(g_rangemark_path, g_path, sizeof(g_rangemark_path));
				}
			} else xmsg("dir changed, range sel off");
			break;
		case '/':
			{
				char f[NAME_MAXLEN];
				if (readfilter(f, sizeof(f), NULL)) {
					if (f[0]) { xstrlcpy(g_filter, f, sizeof(g_filter)); g_filteractive = 1; }
					else g_filteractive = 0;
				}
				applyfilter();
			}
			break;
		case 't':
			sortprompt(0);
			break;
		case 'T':
			sortprompt(1);
			break;
		case 'n':
			{
				int k = askchoice("['f'ile]/'d'ir/'s'ym/'h'ard?", "fdsh");
				if (k > 0) newentry(k);
			}
			break;
		case 'x':
		case 'X':
			deleteentry();
			break;
		case 'z':
			archiveentry();
			break;
		case 'u':
			remoteentry();
			break;
		case 'c':
			mountremote();
			break;
		case 'o':
			openwith();
			break;
		case '=':
			runapp();
			break;
		case ']':
			shellrepl();
			break;
		case '!':
			spawnshell();
			break;
		case 'p':
			if (!g_nselpts) { xmsg("0 selected"); break; }
			op_paste(0);
			browsedir(g_path);
			refreshsel();
			break;
		case 'v':
			if (!g_nselpts) { xmsg("0 selected"); break; }
			op_paste(1);
			browsedir(g_path);
			refreshsel();
			break;
		case 'w':
			if (!g_nselpts) { xmsg("0 selected"); break; }
			copysmoveas();
			break;
		case 'r':
			if (g_nselpts) {
				int k = askchoice("'c'urrent/'s'el?", "cs");
				if (k < 0) break;
			}
			renamecurrent();
			break;
		case 'B':
			{
				char name[NAME_MAXLEN];
				char *base = strrchr(g_path, '/');
				if (!readstr("name:", name, sizeof(name), base ? base + 1 : g_path)) { xmsg("cancelled"); break; }
				if (!name[0]) { xmsg("cancelled"); break; }
				xmsg("failed!");
			}
			break;
		case 'b':
			{
				char p[PATH_MAXLEN];
				snprintf(p, sizeof(p), "%s/.config/nnn/bookmarks", g_home);
				setpath(p);
				{
					char f[NAME_MAXLEN];
					if (readfilter(f, sizeof(f), NULL)) {
						if (f[0]) { xstrlcpy(g_filter, f, sizeof(g_filter)); g_filteractive = 1; }
						else g_filteractive = 0;
					}
					applyfilter();
				}
			}
			break;
		case 's':
			sessionprompt();
			break;
		case 'S':
			showselsize();
			break;
		case 'J':
			jumprompt();
			break;
		case 'q':
			if (g_quitconf && g_nselpts) {
				int k = askchoice("'q'uit?", "qy");
				if (k < 0) break;
			}
			quitnnn(0);
			return;
		case 'Q':
			quitnnn(0);
			return;
		default:
			break;
		}
	}
}
