static void applyfilter(void)
{
	int i, n = 0;
	if (!g_filteractive || !g_filter[0]) {
		browsedir(g_path);
		refreshsel();
		return;
	}
	{
		struct entry *out = calloc(g_ndents ? g_ndents : 1, sizeof(struct entry));
