{
	if (g_pickfile) {
		FILE *f;
		int i;
		if (!strcmp(g_pickfile, "-")) f = stdout;
		else f = fopen(g_pickfile, "w");
		if (f) {
			for (i = 0; i < g_nselpts; ++i) {
				fwrite(g_selpaths[i], 1, strlen(g_selpaths[i]), f);
				fputc(g_nullsep ? 0 : '\n', f);
			}
			fclose(f);
		}
	} else save_selection();
	if (g_persist) save_session(NULL);
	endwin();
	exit(code);
}
