/* ---------------- external commands and file operations ---------------- */
#include "includes.h"

int runcmd(const char *cmd, const char *arg1, const char *arg2)
{
	pid_t pid;
	int st = 0;
	fflush(stdout);
	pid = fork();
	if (pid == 0) {
		char buf[PATH_MAXLEN * 2];
		if (arg1 && arg2) snprintf(buf, sizeof(buf), "%s '%s' '%s'", cmd, arg1, arg2);
		else if (arg1) snprintf(buf, sizeof(buf), "%s '%s'", cmd, arg1);
		else snprintf(buf, sizeof(buf), "%s", cmd);
		execl("/bin/bash", "/bin/bash", "-c", buf, (char *)NULL);
		_exit(127);
	} else if (pid > 0) {
		waitpid(pid, &st, 0);
	}
	if (WIFEXITED(st)) return WEXITSTATUS(st);
	return 1;
}

void pressenter(void)
{
	clear();
	mvprintw(1, 0, "'Enter' to continue");
	refresh();
	(void)getch();
	clear();
}

int shellcmd(const char *cmd)
{
	int r = runcmd(cmd, NULL, NULL);
	pressenter();
	return r;
}

void openentry(const char *path, const char *app, int guicli)
{
	char cmd[PATH_MAXLEN * 2];
	if (app) {
		if (guicli == 'c') snprintf(cmd, sizeof(cmd), "%s '%s'", app, path);
		else snprintf(cmd, sizeof(cmd), "%s '%s' >/dev/null 2>&1 &", app, path);
		runcmd(cmd, NULL, NULL);
		return;
	}
	if (g_opener) {
		snprintf(cmd, sizeof(cmd), "%s '%s'", g_opener, path);
		runcmd(cmd, NULL, NULL);
		return;
	}
}

void editfile(const char *path)
{
	const char *ed = g_visual ? g_visual : (g_editor ? g_editor : "vi");
	char cmd[PATH_MAXLEN * 2];
	snprintf(cmd, sizeof(cmd), "%s '%s'", ed, path);
	runcmd(cmd, NULL, NULL);
	pressenter();
}

void op_delete(const char *path)
{
	char cmd[PATH_MAXLEN * 3];
	snprintf(cmd, sizeof(cmd), "rm -rf '%s'", path);
	runcmd(cmd, NULL, NULL);
}

void op_deleteall(void)
{
	int i;
	for (i = 0; i < g_nselpts; ++i) op_delete(g_selpaths[i]);
}

void op_paste(int move)
{
	int i;
	for (i = 0; i < g_nselpts; ++i) {
		char cmd[PATH_MAXLEN * 3];
		const char *c = move ? (g_advcp ? "mvg" : "mv") : (g_advcp ? "cpg" : "cp");
		snprintf(cmd, sizeof(cmd), "%s '%s' .", c, g_selpaths[i]);
		runcmd(cmd, NULL, NULL);
	}
	pressenter();
}

void op_archive(const char *name)
{
	char cmd[PATH_MAXLEN * 4];
	int i;
	if (g_nselpts) {
		char *list = malloc(g_nselpts * (PATH_MAXLEN + 4) + 8);
		size_t p = 0;
		list[0] = '\0';
		for (i = 0; i < g_nselpts; ++i)
			p += snprintf(list + p, g_nselpts * (PATH_MAXLEN + 4) + 8 - p, " '%s'", g_selpaths[i]);
		snprintf(cmd, sizeof(cmd), "tar czf '%s'%s", name, list);
		free(list);
	} else if (g_ndents)
		snprintf(cmd, sizeof(cmd), "tar czf '%s' '%s'", name, g_dents[g_cur].name);
	else return;
	runcmd(cmd, NULL, NULL);
	pressenter();
}

void op_renamebatch(void)
{
	char tmpl[] = "/tmp/.nnnXXXXXX";
	int fd = mkstemp(tmpl);
	FILE *f;
	char buf[PATH_MAXLEN * 2];
	int i, nn = 0;
	char names[MAXSEL][NAME_MAXLEN];

	if (fd < 0) { quitnnn(1); return; }
	f = fdopen(fd, "w");
	if (!f) { quitnnn(1); return; }
	if (g_nselpts)
		for (i = 0; i < g_nselpts; ++i) fprintf(f, "%s\n", g_selnames[i]);
	else if (g_ndents)
		fprintf(f, "%s\n", g_dents[g_cur].name);
	fclose(f);
	if (g_visual) snprintf(buf, sizeof(buf), "%s '%s'", g_visual, tmpl);
	else if (g_editor) snprintf(buf, sizeof(buf), "%s '%s'", g_editor, tmpl);
	else snprintf(buf, sizeof(buf), "vi '%s'", tmpl);
	endwin();
	runcmd(buf, NULL, NULL);
	/* apply the renames */
	if (g_nselpts)
		for (i = 0; i < g_nselpts; ++i) xstrlcpy(names[nn++], g_selnames[i], NAME_MAXLEN);
	else if (g_ndents)
		xstrlcpy(names[nn++], g_dents[g_cur].name, NAME_MAXLEN);
	{
		FILE *fr = fopen(tmpl, "r");
		char line[PATH_MAXLEN];
		int n = 0;
		while (fr && nn && fgets(line, sizeof(line), fr)) {
			size_t l = strlen(line);
			while (l && (line[l - 1] == '\n' || line[l - 1] == '\r')) line[--l] = '\0';
			if (n < nn && strcmp(line, names[n])) {
				char cmd[PATH_MAXLEN * 3];
				snprintf(cmd, sizeof(cmd), "mv '%s' '%s'", names[n], line);
				runcmd(cmd, NULL, NULL);
			}
			++n;
			if (n >= nn) break;
		}
		if (fr) fclose(fr);
	}
	unlink(tmpl);
	pressenter();
}
