{"command": "cat > /workspace/src/ops.c <<'CEOF'
/* ---------------- external commands and file operations ---------------- */
#include "includes.h"

int runcmd(const char *cmd, const char *arg1, const char *arg2)
{
	pid_t pid;
	int st = 0;
	fflush(stdout);
	pid = fork();
	if (pid == 0) {
		char buf[PATH_MAXLEN * 2];
		if (arg1 && arg2) snprintf(buf, sizeof(buf), "%s '%s' '%s'", cmd, arg1, arg2);
		else if (arg1) snprintf(buf, sizeof(buf), "%s '%s'", cmd, arg1);
		else snprintf(buf, sizeof(buf), "%s", cmd);
		execl("/bin/bash", "/bin/bash", "-c", buf, (char *)NULL);
		_exit(127);
	} else if (pid > 0) {
		waitpid(pid, &st, 0);
	}
	if (WIFEXITED(st)) return WEXITSTATUS(st);
	return 1;
}

void pressenter(void)
{
	clear();
	mvprintw(1, 0, "'Enter' to continue");
	refresh();
	(void)getch();
	clear();
}

int shellcmd(const char *cmd)
{
	int r = runcmd(cmd, NULL, NULL);
	pressenter();
	return r;
}

void openentry(const char *path, const char *app, int guicli)
{
	char cmd[PATH_MAXLEN * 2];
	if (app) {
		if (guicli == 'c') snprintf(cmd, sizeof(cmd), "%s '%s'", app, path);
		else snprintf(cmd, sizeof(cmd), "%s '%s' >/dev/null 2>&1 &", app, path);
		runcmd(cmd, NULL, NULL);
		return;
	}
	if (g_opener) {
		snprintf(cmd, sizeof(cmd), "%s '%s'", g_opener, path);
		runcmd(cmd, NULL, NULL);
		return;
	}
}

void editfile(const char *path)
{
	const char *ed = g_visual ? g_visual : (g_editor ? g_editor : "vi");
	char cmd[PATH_MAXLEN * 2];
	snprintf(cmd, sizeof(cmd), "%s '%s'", ed, path);
	runcmd(cmd, NULL, NULL);
	pressenter();
}

void op_delete(const char *path)
{
	char cmd[PATH_MAXLEN * 3];
