/* helpers: entry suffix, date/perms formatting, listing window */
#include "includes.h"

char entrysuffix(const struct entry *e)
{
	if (e->type == DT_DIR) return '/';
	if (e->type == DT_FIFO) return '|';
	if (e->type == DT_SOCK) return '=';
	if (e->type == DT_BLK) return 'b';
	if (e->type == DT_CHR) return 'c';
	if (e->type == DT_LNK) return '@';
	if (e->mode & 0111) return '*';
	return 0;
}

void fmtperms(const struct entry *e, char *buf, size_t n)
{
	snprintf(buf, n, "%o", e->mode);
}

void fmtdate(const struct entry *e, char *buf, size_t n)
{
	struct tm *tm = localtime(&e->mt);
	strftime(buf, n, "%Y-%m-%d %H:%M", tm);
}

void drawlist(void)
{
	int row, i;
	int maxrows = g_rows - 4;
	int avail;

	if (maxrows < 1) maxrows = 1;
	if (g_cur < g_top) g_top = g_cur;
	if (g_cur >= g_top + maxrows) g_top = g_cur - maxrows + 1;
	if (g_top < 0) g_top = 0;

	for (row = 2; row <= g_rows - 1; ++row) {
		move(row, 0);
		clrtoeol();
	}
	move(1, 0);
	clrtoeol();

	avail = g_ndents - g_top;
	if (avail > maxrows) avail = maxrows;
	for (i = 0; i < avail; ++i)
		drawrow(g_top + i, i + 2);

	if (g_ndents > maxrows) {
		move(g_rows - 2, 0);
		addch('v');
	}

	drawstatus();
}

int g_persist, g_advcp, g_nullsep, g_autofifo, g_bsdflag;
int g_scrolllines = 1, g_locksecs = -1, g_fifomode = -1;
char *g_newfile = NULL;

void adjustwinsz(void)
{
	struct winsize w;
	if (ioctl(0, TIOCGWINSZ, &w) == 0 && w.ws_row > 0) { g_rows = w.ws_row; g_cols = w.ws_col; }
}
